#!/usr/bin/env python3
"""Generate the final report from actual held-out outcomes; no inference changes."""
import csv,json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parent

def read(p):return list(csv.DictReader(open(p),delimiter='\t'))
def main():
    checks=json.loads((ROOT/'results/completion_checks.json').read_text());assert checks['status']=='passed'
    metrics=read(ROOT/'results/validation_metrics.tsv');dev=read(ROOT/'results/development_metrics.tsv')
    paths=read(ROOT/'results/validation_path_predictions.tsv');pred=read(ROOT/'results/validation_dosage_predictions.tsv')
    freeze=json.loads((ROOT/'source/validation_freeze.json').read_text());model=json.loads((ROOT/'source/dosage_model.json').read_text())
    audit=read(ROOT/'results/validation_C4_diagnostic_audit.tsv');errors=read(ROOT/'results/validation_errors.tsv')
    cases=json.loads((ROOT/'results/validation_case_summary.json').read_text())
    demographics=read(ROOT/'source/validation_demographics.tsv')
    n=len(pred);names={'targeted_markers':'Targeted fragment probes','C4Investigator':'C4Investigator','reference_depth_WHR1_unique_region':'Reference depth / WHR1','reference_depth_TNXB_distal_region':'Reference depth / TNXB','old_sketch_CN':'Old sketch + total CN','targeted_dosage_paths':'Targeted + marginal dosage','targeted_without_module_context':'Targeted without module contexts'}
    def get(method,feature):return next(r for r in metrics if r['method']==method and r['feature']==feature)
    dosage=[r for r in metrics if r['feature'] in ['total','A','B','OTHER','L','S']]
    lines=['# Targeted RCCX/C4 typing: held-out read experiment','',f'This experiment evaluates {n} newly examined donors after using all 106 previously examined donors for development. All {n} selected families were excluded from assay discovery and candidate reference paths. These samples remain part of the original assembly graph: this is new-donor read validation within the panel, not an independent external-cohort validation.','', '## Marginal dosage','', '| Method | Feature | Correct / attempted | Calls made |','|---|---|---:|---:|']
    for r in dosage:lines.append(f"| {names[r['method']]} | {r['feature']} | {r['correct']}/{r['n']} | {r['called']} |")
    lines += ['', 'Abstentions count as failures in all-attempted accuracy. A/B and long/short are separate marginal dosages; they do not directly determine AL/AS/BL/BS combinations or physical phase. OTHER denotes a noncanonical diagnostic motif, not a confirmed functional allele class.','', '## Structural-pair imputation','', '| Method | Exact signature pair / attempted | Truth retained in compatible set | Median compatible pairs |','|---|---:|---:|---:|']
    for method in ['old_sketch_CN','targeted_dosage_paths','targeted_without_module_context']:
        r=get(method,'full_signature_pair');cov=get(method,'truth_in_dosage_compatible_set');ps=[p for p in paths if p['method']==method]
        lines.append(f"| {names[method]} | {r['correct']}/{n} | {cov['correct']}/{n} | {np.median([int(p['dosage_compatible_pair_count']) for p in ps]):g} |")
    from collections import Counter
    ancestry=dict(Counter(r['superpopulation'] for r in demographics))
    lines += ['',f'Validation superpopulation counts: {ancestry}. There are no EUR donors in this selected set, limiting direct extrapolation to predominantly European UK Biobank samples.',f"Paired structural changes: {cases['changes']}. Post-evaluation error categories: {cases['categories']}. Full donor-level dispositions are in `results/validation_case_analysis.tsv`."]
    main=get('targeted_dosage_paths','full_signature_pair');old=get('old_sketch_CN','full_signature_pair');abl=get('targeted_without_module_context','full_signature_pair')
    lines += ['',f"The targeted model changes exact signature-pair accuracy from {old['correct']}/{n} to {main['correct']}/{n}. Omitting module-start context probes gives {abl['correct']}/{n}. These are small-sample exploratory comparisons; a ranking gain does not establish physical phase or a graph-specific advantage.",'','All compatible reference structure pairs are retained in the prediction table. A unique numerical optimum is labelled imputation, not direct molecular phase. The sets use heuristic dosage calls and are not calibrated confidence sets; dosage errors and absent reference structures can exclude the truth. Full signatures include provisional CYP21/TNX prototype annotations, not established functional alleles.','', '## Assay and development','',f"The reference contains 543 training haplotypes and 1,090 annotated C4 genes. All 299 targeted probes were confined to RCCX in the full training MHC sequences. Whole-genome specificity was not established. Diagnostic groups are counted once per fragment, with canonical exact 31-mers and Q20 filtering. A/B relative efficiency was {model['A_relative_B']['factor']:.4g}; long/short relative efficiency was {model['L_relative_S']['factor']:.4g}. These were fitted using development donors only. Total dosage retains the earlier pilot-derived correction of {model['total_C4_factor']:.6g}.", '',f"The assay was frozen at {freeze['utc']}; the file hashes are in `source/validation_freeze.json`. The 106 development outcomes are exploratory resubstitution results, not new validation. Development C4Investigator covers a prespecified subset of 18; validation C4Investigator covers all {n} donors. Its upstream version and command were fixed independently of the targeted model.",'','## Assembly labels and diagnostic audit','',f"The held-out assembly audit assessed {len(audit)} C4 genes. {sum(r['status']!='match' for r in audit)} differed from the inherited annotation or had incomplete diagnostic alignment. Original annotation comparisons are retained in the main accuracy tables. The full audit is in `results/validation_C4_diagnostic_audit.tsv`.",'','Three training genes had a noncanonical A-like five-site motif (GGTGC), rather than the canonical A motif (CGTGC). Their observations are candidates for further sequence investigation, not validated novel HLA types or functional C4 alleles. Read-level support and assembly-label discordance must be interpreted separately.','', '## Limits and biological interpretation','', 'The read source is public WGS recruited to MHC intervals through existing linear-reference mappings. This tests typing conditional on that recruitment, not whole-WGS recruitment sensitivity. The assembly annotations are comparator labels rather than independent clinical truth. Recorded family exclusion does not rule out all cryptic relatedness.','', 'The long/short HERV feature and A/B diagnostic sites are too far apart for ordinary short fragments to provide their physical linkage. Module-start probes interrogate sequence contexts around WHR1-family annotations; they are not proven SV breakpoints. New structures outside the reference cannot be safely rejected as unknown by the current ranking procedure.','', 'These features can extend classical HLA typing with C4 dosage, HERV state and an explicitly uncertain RCCX structural interpretation. The earlier study identified RCCX variation among haplotypes sharing complete classical two-field HLA labels. Disease association, expression consequences, and added prediction beyond classical HLA require later validation; they are not established here. UK Biobank WGS/WES and phenotype access is available but remains outside this hackathon analysis.','', '## Prior work','', 'C4Investigator already performs comprehensive short-read C4 dosage and sequence analysis; this experiment is not the first C4 structural typing method. Its published limitation on phasing A/B with long/short is directly relevant here. See [Marin et al., HLA, DOI 10.1111/tan.15273](https://doi.org/10.1111/tan.15273), the archived preprint in `literature/`, and [the upstream software](https://github.com/Hollenbach-lab/C4Investigator). Broader graph and RCCX prior art is archived in the preceding HLA studies.','', '## Reproduction and deliverables','', 'Selection, probe construction, counting, calibration, inference, evaluation, post-freeze diagnostic auditing and completion checks are implemented in the scripts in this directory. `PROTOCOL.md` records the split and endpoint definitions. `source/job_manifest.json` records cluster jobs. Large sequence and read-measurement inputs remain excluded from Git; remote paths and regeneration procedures are in `README.md` and the Slurm scripts.','', '- `results/validation_dosage_predictions.tsv`: estimates, calls and abstentions.','- `results/validation_path_predictions.tsv`: ranked pairs and complete dosage-compatible sets.','- `results/validation_metrics.tsv` and `validation_errors.tsv`: all-attempted metrics and disagreements.','- `results/validation_depth_baseline.tsv`: independently calibrated depth comparator.','- `results/validation_C4_diagnostic_audit.tsv`: post-freeze assembly audit.','- `results/completion_checks.json`: provenance and denominator checks.','- `results/validation_summary.png` and `.pdf`: comparison figure.','', 'Repository: https://github.com/leechuck/pangenome-bh26','']
    (ROOT/'REPORT.md').write_text('\n'.join(lines))
    fig,axes=plt.subplots(1,2,figsize=(11,4),layout='constrained')
    features=['total','A','B','L','S'];x=np.arange(len(features))
    for offset,method,color in [(-.18,'targeted_markers','#2166ac'),(.18,'C4Investigator','#b35806')]:
        vals=[int(get(method,f)['correct']) for f in features];axes[0].bar(x+offset,vals,.34,label=names[method],color=color)
    axes[0].set_xticks(x,features);axes[0].set_ylim(0,n+1);axes[0].set_ylabel(f'Correct calls / {n} attempted');axes[0].set_title('Marginal dosage');axes[0].legend(fontsize=8)
    methods=['old_sketch_CN','targeted_dosage_paths','targeted_without_module_context'];vals=[int(get(m,'full_signature_pair')['correct']) for m in methods]
    axes[1].bar(range(3),vals,color=['#888888','#2166ac','#67a9cf']);axes[1].set_xticks(range(3),['Old sketch','Targeted','Without module\ncontexts']);axes[1].set_ylim(0,n+1);axes[1].set_title('Structural-pair imputation');axes[1].set_ylabel(f'Exact signature pairs / {n}')
    fig.suptitle('New-donor read validation within the assembly panel',fontsize=12)
    for ext in ['png','pdf']:fig.savefig(ROOT/f'results/validation_summary.{ext}',dpi=180)
    plt.close(fig)
    print('Wrote REPORT.md and validation_summary figures')
if __name__=='__main__':main()
